import{_ as o,o as r,c as e,a5 as l}from"./chunks/framework.DJo0M80U.js";const c=JSON.parse('{"title":"各配置项的执行顺序","description":"Vue 配置项和生命周期钩子的执行顺序 1. 初始化 props ： 执行 props 配置项中的数据验证和默认值处理。 在此阶段，组件实例还未生成，只是对传入的 props 进行处理。 2. 创建组件实例 ： 创建组件实例，此时会调用 beforeCreate 生命周期钩子。","frontmatter":{"title":"各配置项的执行顺序","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","模板、组件与交互"],"description":"Vue 配置项和生命周期钩子的执行顺序 1. 初始化 props ： 执行 props 配置项中的数据验证和默认值处理。 在此阶段，组件实例还未生成，只是对传入的 props 进行处理。 2. 创建组件实例 ： 创建组件实例，此时会调用 beforeCreate 生命周期钩子。","sidebarWeight":13,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/api/Vue 生命周期方法详解/各配置项的执行顺序.md"},"headers":[],"relativePath":"posts/Vue系统教程/02-模板、组件与交互/Vue 生命周期方法详解/各配置项的执行顺序.md","filePath":"posts/Vue系统教程/02-模板、组件与交互/Vue 生命周期方法详解/各配置项的执行顺序.md"}'),s={name:"posts/Vue系统教程/02-模板、组件与交互/Vue 生命周期方法详解/各配置项的执行顺序.md"};function i(n,t,g,a,u,p){return r(),e("div",null,[...t[0]||(t[0]=[l('<div><h1 id="各配置项的执行顺序" tabindex="-1">各配置项的执行顺序 <a class="header-anchor" href="#各配置项的执行顺序" aria-label="Permalink to &quot;各配置项的执行顺序&quot;">​</a></h1><blockquote><p>本节目标：理解“各配置项的执行顺序”的核心思路，并能把它用于实际开发或面试表达。 <strong>Vue 配置项和生命周期钩子的执行顺序</strong></p></blockquote><ol><li><strong>初始化 props</strong>： <ul><li>执行 props 配置项中的数据验证和默认值处理。</li><li>在此阶段，组件实例还未生成，只是对传入的 props 进行处理。</li></ul></li><li><strong>创建组件实例</strong>： <ul><li>创建组件实例，此时会调用 beforeCreate 生命周期钩子。</li></ul></li><li><strong>初始化组件数据</strong>： <ul><li>执行 data 配置项中的函数或对象，将返回值与组件实例的数据进行合并，生成组件实例的响应式数据。</li></ul></li><li><strong>执行生命周期钩子 created</strong>： <ul><li>执行 created 钩子函数，此时可以访问组件实例的数据和方法，但 DOM 还未生成。</li></ul></li><li><strong>初始化 computed</strong>： <ul><li>执行 computed 配置项中的函数，生成计算属性，并将其定义为组件实例的响应式数据。</li></ul></li><li><strong>初始化 watch</strong>： <ul><li>执行 watch 配置项中的函数，生成观察者，并将其订阅到组件实例的响应式数据上，监听数据的变化。</li></ul></li><li><strong>执行生命周期钩子 beforeMount</strong>： <ul><li>在挂载开始之前调用 beforeMount 钩子，此时模板已经编译完毕，但还未挂载到 DOM 上。</li></ul></li><li><strong>挂载组件</strong>： <ul><li>将编译后的模板挂载到 DOM 上，执行 mounted 钩子函数，此时可以进行 DOM 操作。</li></ul></li></ol><p><strong>当组件实例的响应式数据发生变化时</strong></p><ul><li><strong>响应式更新</strong>： <ul><li>当组件实例的响应式数据发生变化时，依赖此数据的 watcher 会被触发，更新 DOM 并执行相应的回调函数。</li></ul></li></ul><p><strong>执行顺序总结</strong></p><ol><li><strong>初始化 props</strong></li><li><strong>创建组件实例</strong>：调用 beforeCreate</li><li><strong>初始化 data</strong></li><li><strong>调用 created</strong></li><li><strong>初始化 computed</strong></li><li><strong>初始化 watch</strong></li><li><strong>调用 beforeMount</strong></li><li><strong>挂载组件</strong>：调用 mounted</li></ol><p><strong>细节说明</strong></p><ul><li><strong>beforeCreate</strong>：此时无法访问 data 和 props。</li><li><strong>created</strong>：可以访问 data 和 props，但 DOM 未生成。</li><li><strong>beforeMount</strong>：模板已编译完毕，但未挂载到 DOM 上。</li><li><strong>mounted</strong>：DOM 已挂载，可以进行 DOM 操作。</li></ul><p><strong>应用实例</strong> 在实际应用中，根据不同的生命周期钩子，可以执行不同的操作：</p><ul><li><strong>beforeCreate</strong>：很少使用，通常用于全局混入或插件的初始化。</li><li><strong>created</strong>：可以进行初始化数据的获取、事件监听的设置等。</li><li><strong>beforeMount</strong>：很少使用，可以在此处修改数据以影响初次渲染。</li><li><strong>mounted</strong>：通常用于获取或操作 DOM 元素。</li><li><strong>beforeUpdate</strong>：数据更新之前可以在此处执行操作，如手动修改状态。</li><li><strong>updated</strong>：数据更新之后，可以操作更新后的 DOM 元素。</li><li><strong>beforeDestroy</strong>：执行清理任务，如清除定时器、事件监听器。</li><li><strong>destroyed</strong>：实例销毁后，进行清理操作，如解除绑定、清理内存等。</li></ul><p>这个调整后的顺序和解释应该能更准确地描述 Vue 配置项和生命周期钩子的执行顺序。</p></div>',1)])])}const _=o(s,[["render",i]]);export{c as __pageData,_ as default};
